            std::vector<float> weight_square = weight;
            // std::vector<unsigned> dim_start_list(dim_list.size(), 0), dim_end_list = dim_list;
            std::vector<const float *> vectors1(dim_list.size(), nullptr), vectors2(dim_list.size(), nullptr);
            // bool notFirstRound = false;

