                            // // RETURN POS CHECK
                            // std::cout << "__  【In largeFirst_sqrt()】: return at pos 1 , with one-step zero-round end: -1 __" << std::endl;
                            // float kDist_est_dist = compare_weight_adsampling_half_dim_read_v3_kDist_est(base1, id1, base2, id2, dim_list, read_end_dim_ratio, thresh_rate_square, need_calcu,
                            //                                                     weight, k_dist, max_dist, diameter, epsilon0, step); 
                            // std::cout << "-- return -1; kDist_est_dist = " << kDist_est_dist << std::endl;
                            // // RETURN POS CHECK End
                            
                            // float dist2 = compare_smart_weight(base1, id1, base2, id2, dim_list, need_calcu, weight, max_dist);
