                                    //     std::cout <<  "                 thresh_k: " << thresh_k << ", thresh_max: " << thresh_max << std::endl;
                                    // }
                                    // // DEBUG END
                                    // break;
                                    
                                    // // ### POS CHECK
                                    // float kDist_est_dist = compare_weight_adsampling_half_dim_read_v3_kDist_est(base1, id1, base2, id2, dim_list, read_end_dim_ratio, thresh_rate_square, need_calcu,
                                    //                                             weight, k_dist, max_dist, diameter, epsilon0, step); 
