                                // // DEBUG START
                                // float true_dist = compare_smart_weight(base1, id1, base2, id2, dim_list, need_calcu, weight);
                                // std::cout << "-- RETURN: est_dist(pos1.3): " << est_dist << ", with true_dist: " << true_dist << "; k_dist: " << k_dist << ", max_dist" << max_dist << std::endl;
                                // // DEBUG END

                                // // RETURN POS CHECK
                                // std::cout << "__ 【In largeFirst_sqrt()】: return at pos 2, with one-step zero-round end: <= max_dist __" << std::endl;
                                // float kDist_est_dist = compare_weight_adsampling_half_dim_read_v3_kDist_est(base1, id1, base2, id2, dim_list, read_end_dim_ratio, thresh_rate_square, need_calcu,
                                //                                                 weight, k_dist, max_dist, diameter, epsilon0, step); 
