                // std::cout << "---------------------------------------------------------" << std::endl;
                // // ### CHECK END

                
                // ----- 3. 进行剩余计算 -----
                // if (need_round1 > thresh_rate_square.size()) {
                //     need_round1 = thresh_rate_square.size();
