                                    // std::cout << " -- field_scores[i].idx before order: ";
                                    // for (int i = 0; i < num_fields; i++)
                                    // {
                                    //     std::cout << field_scores[i].idx << ", ";
                                    // }
                                    // std::cout << std::endl;

