                //                                                                 weight, k_dist, max_dist, diameter, epsilon0, step);
                // -- 2. latency
                float dist1 = compare_weight_adsampling_half_dim_read_v3_kDist_est(base1, id1, base2, id2, dim_list, read_end_dim_ratio, thresh_rate_square, need_calcu,
                                                                                weight, k_dist, max_dist, diameter, epsilon0, step);   
