                //                                                                 weight, k_dist, max_dist, diameter, step, alpha);  
                // -- 2. latency
                float dist2 = compare_weight_adsampling_v3_kDist_diameter_largeFirst_sqrt(base1, id1, base2, id2, dim_list, need_calcu,
                                                                                weight, k_dist, max_dist, diameter, step, alpha);
                // std::cout << "dist2 = " << dist2 << std::endl;
                auto e2 = std::chrono::high_resolution_clock::now();
                                                                    
                dec++;
                std::chrono::duration<double> diff1 = (e1-s1), diff2 = (e2-s2);
                dec1_cost += diff1.count();
                dec2_cost += diff2.count();
                // std::cout << "cand1 dim: " << diff1.count() << " seconds, cand2 dim: " << diff2.count() << " seconds." << std::endl;
