        // ---------------- JL 误差与 per-field LB ----------------

        // // c0 = 1/4
        // static inline float AESC_eps_per_field(unsigned used_i, int m_fields, float alpha) {
        //     if (used_i == 0) return 0.0f;
        //     const float c0 = 0.25f;
        //     // JL bound: eps_i(used_i) = sqrt( ln(2m / alpha) / (c0 * used_i) )
        //     // float numer = std::log(2.0f * static_cast<float>(m_fields) / alpha);
        //     float numer = std::log(2.0f * static_cast<float>(m_fields) / alpha);
        //     if (numer < 0.0f) numer = 0.0f; // 安全兜底
        //     float eps = std::sqrt(numer / (c0 * static_cast<float>(used_i)));
        //     return eps;
        // }
        static inline float AESC_eps_per_field(unsigned end_dim, int num_conti, float p_alpha) {
            // const float c0 = 0.25f;
            // JL bound: eps_i(used_i) = sqrt( ln(2m / alpha) / (c0 * used_i) )
            // float eps = std::sqrt((2.0f * std::log((float)num_conti / p_alpha)) / (0.25f * end_dim));  // ## (oneSide)
            float eps = std::sqrt((std::log((float)num_conti / p_alpha)) / (0.25f * end_dim));  // ## (twoSide)
            return eps;
        }

        // 计算单 field 的 LB_i(used_i)
        // dim_i: 该 field 总维度 d_i
        // used_i: 当前使用维度 used_i
        // partial_sq_i: 当前累计的 ||P_i x_i||^2 (前 used_i 维)
        // weight_i: 该 field 的权重 w_i
        // m_fields: 参与本次比较的 field 数量
        // alpha: 置信度参数
        static inline float AESC_LB_single_field(unsigned dim_i,
                                                unsigned used_i,
                                                float partial_sq_i,
                                                float weight_i,
                                                int m_fields,
                                                float alpha) {
            if (used_i == 0 || weight_i <= 0.0f) return 0.0f;

            if (used_i >= dim_i) {
                // 已经用完所有维度，partial_sq_i 就是真实 ||x_i||^2
                float true_norm = std::sqrt(std::max(partial_sq_i, 0.0f));
                return weight_i * true_norm;
            }

            // 估计 full-dim norm： \hat d_i(used_i) = sqrt( (d_i / used_i) * partial_sq_i )
            float scale = static_cast<float>(dim_i) / static_cast<float>(used_i);
            float d_hat = std::sqrt(std::max(scale * partial_sq_i, 0.0f));

            // 误差 eps_i(used_i)
            float eps = AESC_eps_per_field(used_i, m_fields, alpha);

            // LB_i(used_i) = w_i * d_hat / sqrt(1 + eps_i)
            // float factor = 1.0f / std::sqrt(1.0f + eps); // 这个写错了吧？
            float factor = 1.0f / (1.0f + eps);
            return weight_i * d_hat * factor;
        }

        // 计算 “仅考虑分母变化” 的 LB_i 关于 used_i 的导数近似
        // eps = eps_i(used_i)
        // used_i > 0
        static inline float AESC_LB_denom_only_grad(float LB_i, float eps, unsigned used_i) {
            if (used_i == 0) return 0.0f;
            // 推导结果： grad_denom_only ≈ LB_i * eps / (4 * used_i * (1 + eps))
            float denom = 4.0f * static_cast<float>(used_i) * (1.0f + eps);
            if (denom <= 0.0f) return 0.0f;
            return LB_i * eps / denom;
        }

