    /** XMT, 2025.12.08: 4-2-recordLBi
     * compare_weight_AESC_newTryV4_adaptiveSampling_adaptiveProj()
     *      新版本：多 field 自适应 sampling + 自适应 DCHT threshold
     */
    /** 基于这个的修改2025.10.21 --》 简单还原对比尝试（不est到第几轮能结束）
     * compare_weight_adsampling_half_dim_read_v3_kDist_est_adaptivePro_v2_2()
     * 
     *      先对need_calcu_NoProj中的数据进行计算；然后再对need_calcu_WithProj部分进行AESC
     *      算一个step位，根据est的结果决定下一个round要走到哪里
     * 
     * 新修改的还原尝试：
     *      restore-1. （不est到第几轮能结束）
     *      restore-2. 计算完的部分直接从k_dist, max_dist中扣除。
     * 
     */
    float compare_weight_AESC_newTryV4_adaptiveSampling_adaptiveProj(
            // bool &use_flag,
            int &use,
            float &dec1_cost, float &dec2_cost, int &dec,
            const std::vector<float *> &base1, unsigned id1,
            const std::vector<float *> &base2, unsigned id2,
            const std::vector<unsigned> &dim_list,
            // const std::vector<std::vector<float>> &read_end_dim_ratio,
            const std::vector<float> &dim_sqrt,
            // const std::vector<float> &thresh_rate_square,
            const std::vector<std::vector<float>> &dim_thresh_rate_square, // 全部dimension的
            // const std::vector<std::vector<float>> &dim_thresh_rate_square_inverse, // 全部dimension的
            const std::vector<int> &needCalField,
            const std::vector<int> &need_calcu_NoProj, const std::vector<int> &need_calcu_WithProj,
            std::vector<bool> &do_proj,                                // 保留接口，不使用
            std::vector<float> &weight,
            float k_dist, float max_dist, float diameter,
            float epsilon0,                                            // 不再使用
            unsigned step = 32,
            float alpha = 0.5                                               // 作为 p_alpha 使用
    )
    {
        unsigned first_step = 32;
        
        // std::cout << "---------- In compare_weight_adsampling_half_dim_read_v3_kDist_est_adaptivePro_v2_2(), pos 1" << std::endl;
        // ======= 1. 对need_calcu_NoProj中的数据进行计算 & 早停止 ===================================================================
        float dist_no_proj = 0.0;
        const float *a;
        const float *b;
        float d0, d1, d2, d3;
        const int num_fields = need_calcu_WithProj.size();
        int conti_fields = need_calcu_WithProj.size();
        int get_dim_thresh_rate_square_pos = (1 << (base1.size())) + conti_fields - 1;

        for (auto field : need_calcu_NoProj)
        {
            // std::cout << "Calculting distance in field " << field << std::endl;
            unsigned dim = dim_list[field];
            const float *a = base1[field] + id1 * dim;
            const float *b = base2[field] + id2 * dim;
            {
                // float dist = 0.0;
                // float diff0, diff1, diff2, diff3;
                float dist = 0.0;
                float diff0, diff1, diff2, diff3;
                const float *last = a + dim;
                const float *unroll_group = last - 3;

                /* Process 4 items with each loop for efficiency. */
                while (a < unroll_group)
                {
                    diff0 = a[0] - b[0];
                    diff1 = a[1] - b[1];
                    diff2 = a[2] - b[2];
                    diff3 = a[3] - b[3];
                    dist += diff0 * diff0 + diff1 * diff1 + diff2 * diff2 + diff3 * diff3;
                    a += 4;
                    b += 4;
                }
                /* Process last 0-3 pixels.  Not needed for standard vector lengths. */
                while (a < last)
                {
                    diff0 = *a++ - *b++;
                    dist += diff0 * diff0;
                }

                dist = std::sqrt(dist); // 距离计算是否加sqrt()
                // std::cout << "  dist = " << dist << std::endl;
                dist_no_proj += weight[field] * dist;
                // std::cout << dist_no_proj << ", ";
                // print_full_precision(dist_no_proj);
                // std::cout << ", ";

                if (static_cast<float>(dist_no_proj) > max_dist)
                {
                    return -1;
                }
                // if (dist_no_proj > max_dist) { return dist_no_proj; }
            }
        }

        // return dist_no_proj;
        // return static_cast<float>(dist_no_proj);
        if (num_fields == 0) { return static_cast<float>(dist_no_proj); }
        k_dist -= dist_no_proj;
        max_dist -= dist_no_proj;


        // std::cout << "---------- In compare_weight_adsampling_half_dim_read_v3_kDist_est_adaptivePro_v2_2(), pos 2" << std::endl;

        
        
        
        // ======= 2. 对need_calcu_WithProj中的数据开始 AESC ===================================================================
        // ===== 预处理阶段（该函数的全局变量） =====
        // const float max_dist_sq = max_dist * max_dist;
        // const float k_dist_sq = k_dist * k_dist;
        float k_dist_sq = k_dist * k_dist;
        unsigned max_rounds = 0;
        float total_est_sq = 0.0f;
        float tmp_LB_sq = 0.0f;

        // --- 第一轮推进结束位置 ---
        float thresh_sq_thresh = MAXFLOAT;
        
        // // ## Debug
        // std::cout << "-- thresh_sq_thresh: " << thresh_sq_thresh << std::endl;
        // std::cout << "-- smallest_round: " << smallest_round << std::endl;
        // // ## Debug End

        // 使用固定大小数组避免vector开销（需确保num_fields不大）
        struct FieldMeta
        {
            const float *a_ptr;
            const float *b_ptr;
            float weight;
            float accum_dist_sq;
            float accum_weighted_dist_sq;
            // const float *ratio_ptr;
            unsigned dim;
            unsigned this_round_start;
            unsigned this_round_end;
            unsigned its_step;
            float dim_ratio_sqrt; // sqrt(Di/used_dim_i) (开平方)
            float LB_i;
        };
        FieldMeta fields[32]; // 假设字段数不超过32

        unsigned max_dim = 0;
        unsigned round = 0;
        for (int i = 0; i < num_fields; ++i)
        {
            const int f = need_calcu_WithProj[i];
            const unsigned dim = dim_list[f];
            fields[i] = {
                base1[f] + id1 * dim,
                base2[f] + id2 * dim,
                weight[f],
                0.0f,
                0.0f,
                // read_end_dim_ratio[f].data(),
                dim,
                0,
                0,
                // step,
                first_step,
                0.0f,
                0.0f,
            };
            max_dim = std::max(max_dim, dim);
        }
        if (max_dim) {
            max_rounds = (max_dim-1)/step + 1;
        }
        // std::cout << "---------- In compare_weight_adsampling_half_dim_read_v3_kDist_est_adaptivePro_v4(), pos 3" << std::endl;

        // ===== 分层计算阶段 =====
        // ----- 1. 第一轮推进：用step位计算，为下一步est做准备 -------
        // -- 1.1 每个field用自己的its_step大小推进；在每轮结束/开始的时候决定下一轮的step是多少
        {

            // 使用指针遍历避免迭代器开销
            for (int i = 0; i < num_fields; ++i)
            {
                FieldMeta &field = fields[i];
                // const unsigned begin = round * step;
                // if (begin >= field.dim)
                //     continue;

                const unsigned curr_dim = std::min(field.its_step, field.dim);
                field.this_round_start = field.this_round_end;
                field.this_round_end += curr_dim;
                // field.dim_ratio = field.ratio_ptr[round];
                // field.dim_ratio_sqrt = dim_sqrt[field.dim-1] / dim_sqrt[field.this_round_end-1];
                // const float *a = field.a_ptr;
                // const float *b = field.b_ptr;
                a = field.a_ptr;
                b = field.b_ptr;
                // float dist_sq = 0.0f;
                float dist_sq = field.accum_dist_sq;

                // 4路展开（对比时间）
                unsigned j = 0;
                for (; j + 4 <= curr_dim; j += 4)
                {
                    // const float *aj = a + j;
                    // const float *bj = b + j;
                    // float d0 = aj[0] - bj[0], d1 = aj[1] - bj[1];
                    // float d2 = aj[2] - bj[2], d3 = aj[3] - bj[3];

                    d0 = a[0] - b[0], d1 = a[1] - b[1];
                    d2 = a[2] - b[2], d3 = a[3] - b[3];
                    a+=4, b+=4;
                    dist_sq += d0 * d0 + d1 * d1 + d2 * d2 + d3 * d3;
                }

                // 剩余处理（改用掩码避免分支）
                for (; j < curr_dim; ++j)
                {
                    // float d = a[j] - b[j];
                    // dist_sq += d * d;
                    d0 = a[0] - b[0];
                    a++, b++;
                    dist_sq += d0 * d0;
                }

                // restore-2. 计算完的部分直接从k_dist, max_dist中扣除。
                if (field.dim <= field.its_step){
                    float tmp_dist = field.weight * std::sqrt(dist_sq);
                    dist_no_proj += tmp_dist;
                    k_dist -= tmp_dist;
                    max_dist -= tmp_dist;
                    k_dist_sq = k_dist * k_dist;
                    field.this_round_end = field.dim;
                    conti_fields--;
                    get_dim_thresh_rate_square_pos--;
                }
                else {
                    // field.accum_dist_sq += dist_sq;
                    field.accum_dist_sq = dist_sq;
                    field.accum_weighted_dist_sq = dist_sq * field.weight * field.weight;
                    // total_est_sq += static_cast<float>(field.ratio_ptr[round] * field.accum_dist_sq) * field.weight * field.weight;
                    // total_est_sq += static_cast<float>(field.ratio_ptr[round] * field.accum_weighted_dist_sq);
                    // tmp_LB_sq += static_cast<float>(field.dim_ratio * field.accum_weighted_dist_sq) / thresh_rate_square[round];
                    field.dim_ratio_sqrt = dim_sqrt[field.dim-1] / dim_sqrt[field.this_round_end-1];
                    field.LB_i = static_cast<float>(field.dim_ratio_sqrt * field.dim_ratio_sqrt * field.accum_weighted_dist_sq) / dim_thresh_rate_square[get_dim_thresh_rate_square_pos][field.this_round_end-1];
                    tmp_LB_sq += field.LB_i;
                    // tmp_LB_sq += static_cast<float>(field.dim_ratio_sqrt * field.dim_ratio_sqrt * field.accum_weighted_dist_sq) * dim_thresh_rate_square_inverse[get_dim_thresh_rate_square_pos][field.this_round_end-1];
                }
                // std::cout << "tmp_LB_sq = " << tmp_LB_sq << std::endl;
            }

            // 提前终止判断（使用预计算阈值）
            if (tmp_LB_sq > static_cast<float>(k_dist_sq) * (1.0+1e-4)) // 精度控制：(1.0+1e-4) 
            {
                if (tmp_LB_sq > static_cast<float>(max_dist * max_dist) * (1.0+1e-4)) // 精度控制：(1.0+1e-4)
                {
                    // // ### CHECK END POS
                    // std::cout << "Return at pos 1 (-1), with zero_round_step = " << (smallest_round*step) << std::endl;
                    // // ### CHECK END POS END
                    return -1.0f;
                }
                else
                {
                    float est_dist = 0.0f;
                    // unsigned thresh = std::sqrt(thresh_rate_square[round]) * max_dist;
                    for (int i = 0; i < num_fields; ++i)
                    {
                        if (fields[i].dim > fields[i].this_round_end) { //没结束的部分
                            // 使用快速平方根近似（精度足够时可替换std::sqrt）
                            // est_dist += fields[i].weight * static_cast<float>(std::sqrt(fields[i].accum_dist_sq * fields[i].ratio_ptr[round]));
                            est_dist += static_cast<float>(std::sqrt(fields[i].accum_weighted_dist_sq) * fields[i].dim_ratio_sqrt);
                            // if (est_dist > thresh) {
                            //     return -1.0f;
                            // }
                        }
                    }
                    if (est_dist <= max_dist) {
                        // // ### CHECK END POS
                        // std::cout << "Return at pos 1 (<= max_dist), with zero_round_step = " << (smallest_round*step) << std::endl;
                        // // ### CHECK END POS END
                        // if (est_dist + dist_no_proj == 0) {
                        //     std::cerr << " est_dist + dist_no_proj == 0 at pos 1" << std::endl;
                        //     exit(-6);
                        // }
                        return est_dist + dist_no_proj;
                    }
                }
            }

            // -- 1.2 在每轮结束/开始的时候决定下一轮的step是多少
            for (int i = 0; i < num_fields; ++i) {
                FieldMeta &field = fields[i];
                // -- 【先简单都用step，之后换成根据gradient的】
                field.its_step = std::min(step, field.dim - field.this_round_end);
                // total_step * field.
            }
        }

        // std::cout << "---------- In compare_weight_adsampling_half_dim_read_v3_kDist_est_adaptivePro_v4(), pos 4, max_rounds = " << max_rounds << std::endl;

        if (max_rounds >= 1) {
            // // --- 2. est：预测需要走到第几个round才能停止【不est了】
            // float need_thresh1 = total_est_sq / k_dist_sq;
            // // // float need_thresh1 = diameter * diameter / k_dist_sq;
            // // // [找round方法1]:
            // // round++;
            // // // for (; round < max_rounds - 1; round++) {
            // // for (; round < max_rounds; round++) {
            // //     if (thresh_rate_square[round] < need_thresh1) {
            // //         // unsigned stop_dim = need_round1 * step;
            // //         break;
            // //     }
            // // }
            // // if (round == max_rounds) {round--;}

            // // [找round方法2]:
            // // --- 替换为二分查找 --
            // {
            //     size_t left = 1, right = max_rounds - 1;
            //     if (thresh_rate_square[right] >= need_thresh1) {
            //         round = right;
            //     } else if (thresh_rate_square[left] <= need_thresh1) {
            //         round = left;
            //     }
            //     else {
            //         while (left < right) {
            //             size_t mid = left + (right - left) / 2;
            //             if (thresh_rate_square[mid] <= need_thresh1) {
            //                 round = mid;
            //                 right = mid - 1;  // 继续向左找
            //             } else {
            //                 left = mid + 1;
            //             }
            //         }
            //     }
            // }
            round = 1;
                

            // --- 2. 每轮共推进（num_fields）*step位
            while (conti_fields)
            {
                // total_est_sq = 0.0f;
                tmp_LB_sq = 0.0f;
                // unsigned star_dim = step;
                // unsigned delta_dim = round * step;
                // unsigned end_dim = round * step + step;

                // 使用指针遍历避免迭代器开销
                for (int i = 0; i < num_fields; ++i)
                {
                    // std::cout << "-- Field " << i << std::endl;
                    FieldMeta &field = fields[i];
                    // const unsigned begin = round * step;
                    // if (begin >= field.dim)
                    //     continue;
                    
                    if (field.dim == field.this_round_end) 
                    {
                        // total_est_sq += static_cast<float>(field.accum_weighted_dist_sq);
                        continue;
                    }
                    else 
                    {
                        unsigned curr_dim = field.its_step;
                        field.this_round_start = field.this_round_end;
                        field.this_round_end += curr_dim;
                        a = field.a_ptr + field.this_round_start;
                        b = field.b_ptr + field.this_round_start;
                        // float dist_sq = 0.0f;
                        float dist_sq = field.accum_dist_sq;

                        // 4路展开（对比时间）
                        unsigned j = 0;
                        for (; j + 4 <= curr_dim; j += 4)
                        {
                            d0 = a[0] - b[0], d1 = a[1] - b[1];
                            d2 = a[2] - b[2], d3 = a[3] - b[3];
                            a+=4, b+=4;
                            dist_sq += d0 * d0 + d1 * d1 + d2 * d2 + d3 * d3;
                        }

                        // 剩余处理（改用掩码避免分支）
                        for (; j < curr_dim; ++j)
                        {
                            // float d = a[j] - b[j];
                            // dist_sq += d * d;
                            d0 = a[0] - b[0];
                            a++, b++;
                            dist_sq += d0 * d0;
                        }


                        // restore-2. 计算完的部分直接从k_dist, max_dist中扣除。
                        // std::cout << "field-" << i << "field.dim = " << field.dim << ", field.this_round_end = " << field.this_round_end << ", conti_fields = " << conti_fields << std::endl;
                        if (field.dim <= field.this_round_end){
                            float tmp_dist = field.weight * std::sqrt(dist_sq);
                            dist_no_proj += tmp_dist;
                            k_dist -= tmp_dist;
                            max_dist -= tmp_dist;
                            k_dist_sq = k_dist * k_dist;
                            field.this_round_end = field.dim;
                            conti_fields--;
                            get_dim_thresh_rate_square_pos--;
                            // std::cout << "      conti_fields -> " << conti_fields << std::endl;
                        }
                        else {
                            // field.accum_dist_sq += dist_sq;
                            field.accum_dist_sq = dist_sq;
                            field.accum_weighted_dist_sq = dist_sq * field.weight * field.weight;
                            // total_est_sq += static_cast<float>(field.ratio_ptr[round] * field.accum_weighted_dist_sq);
                            // field.est_weighted_dist_sq = static_cast<float>(field.ratio_ptr[round] * field.accum_weighted_dist_sq);
                            // total_est_sq += field.est_weighted_dist_sq;
                            // tmp_LB_sq += static_cast<float>(field.dim_ratio * field.accum_weighted_dist_sq) / thresh_rate_square[round];
                            field.dim_ratio_sqrt = dim_sqrt[field.dim-1] / dim_sqrt[field.this_round_end-1];
                            field.LB_i = static_cast<float>(field.dim_ratio_sqrt * field.dim_ratio_sqrt * field.accum_weighted_dist_sq) / dim_thresh_rate_square[get_dim_thresh_rate_square_pos][field.this_round_end-1];
                            tmp_LB_sq += field.LB_i;
                            // tmp_LB_sq += static_cast<float>(field.dim_ratio_sqrt * field.dim_ratio_sqrt * field.accum_weighted_dist_sq) * dim_thresh_rate_square_inverse[get_dim_thresh_rate_square_pos][field.this_round_end-1];
                        }
                        // std::cout << "tmp_LB_sq(pos2, round" << round << ") = " << tmp_LB_sq << std::endl;
                    }
                }

                // // ### 提前终止判断（使用预计算阈值）
                if (tmp_LB_sq > static_cast<float>(k_dist_sq) * (1.0+1e-4)) // 精度控制：(1.0+1e-4)
                {
                    if (tmp_LB_sq > static_cast<float>(max_dist * max_dist) * (1.0+1e-4)) // 精度控制：(1.0+1e-4)
                    {
                        return -1.0f;
                    }
                    else
                    {
                        float est_dist = 0.0f;
                        // unsigned thresh = std::sqrt(thresh_rate_square[round]) * max_dist;
                        for (int i = 0; i < num_fields; ++i)
                        {
                            if (fields[i].this_round_end < fields[i].dim) { // 没算完的部分
                                // 使用快速平方根近似（精度足够时可替换std::sqrt）
                                // est_dist += fields[i].weight * static_cast<float>(std::sqrt(fields[i].accum_dist_sq * fields[i].ratio_ptr[round]));
                                est_dist += static_cast<float>(std::sqrt(fields[i].accum_weighted_dist_sq) * fields[i].dim_ratio_sqrt);
                                // if (est_dist > thresh) {
                                //     return -1.0f;
                                // }
                            }
                        }
                        if (est_dist <= max_dist) {
                            // if (est_dist + dist_no_proj == 0) {
                            //     std::cerr << " est_dist + dist_no_proj == 0 at pos 2" << std::endl;
                            //     exit(-6);
                            // }
                            return est_dist + dist_no_proj;
                        }
                    }
                }
                
                // std::cout << "---------- In compare_weight_adsampling_half_dim_read_v3_kDist_est_adaptivePro_v4(), pos 5, round = " << round << ", num_fields = " << num_fields << std::endl;
                round++;
                // -- 2.2 在每轮结束/开始的时候决定下一轮的step是多少
                for (int i = 0; i < num_fields; ++i) {
                    FieldMeta &field = fields[i];
                    // -- 【先简单都用step，之后换成根据gradient的】
                    if (field.this_round_start == field.dim) {field.its_step = 0;}
                    else {
                        field.its_step = std::min(step, field.dim - field.this_round_end);
                    }
                }

            }
        }
        
        return dist_no_proj;
    }

