                    d0 = a[0] - b[0];
                    d1 = a[1] - b[1];
                    d2 = a[2] - b[2];
                    d3 = a[3] - b[3];
                    dist_sq += d0 * d0 + d1 * d1 + d2 * d2 + d3 * d3;
                    a += 4;
