            //             // float alloc = ((field.LB_i_sq - 1.0 )/ tmp_LB_sq + 1.0) * total_need_allo_step;
            //             // float alloc = field.LB_i_sq / tmp_LB_sq * total_need_allo_step;
            //             float alloc = field.LB_i_sq / tmp_LB_sq * total_need_allo_step + 0.5;
            //             // unsigned alloc_step =
            //             //     static_cast<unsigned>(std::ceil(alloc));
            //             // if (alloc_step > remain) alloc_step = remain;
            //             // field.its_step = alloc_step;
            //             // field.its_step = (remain < alloc) ? remain : alloc;
            //             field.its_step = alloc;
            //             // std::cout << "field-" << i << ", total_need_allo_step = " << total_need_allo_step << ", alloc = " << alloc << ", field.its_step = " << field.its_step << std::endl;
            //         }   
            //     } 
            //     else {
            //         for (int i = 0; i < num_fields; ++i) {
            //             FieldMeta &field = fields[i];
            //             if (field.this_round_end >= field.dim) {
            //                 // field.its_step = 0;
            //                 continue;
