            //             // unsigned remain = field.dim - field.this_round_end;
            //             // field.its_step =
            //             //     (remain < step) ? remain : step;
            //             // break;
            //             field.its_step = step;
            //         }
            //     }

            //     // {
            //     //     for (int i = 0; i < num_fields; ++i) {
            //     //         FieldMeta &field = fields[i];
            //     //         if (field.this_round_end >= field.dim) {
            //     //             field.its_step = 0;
            //     //             continue;
            //     //         }
            //     //         unsigned remain = field.dim - field.this_round_end;
            //     //         field.its_step =
