    /** XMT, 2025.12.08: (type 2, V6)
     *  compare_weight_AESC_newTryV6_adaptiveSampling_adaptiveProj()
     *      新版本：多 field block 粒度贪心调度 + 自适应 DCHT threshold
     *
     *  思路：
     *    1) need_calcu_NoProj: 直接算 full-dim，加到 dist_no_proj，从 k_dist/max_dist 中扣除。
     *    2) need_calcu_WithProj:
     *         - 每个 field 先推进一块 step 维，初始化 LB_i^2 和最近斜率 g_i^recent = ΔLB_i^2 / Δused_i。
     *         - 之后循环：
     *             * 按照斜率选择一个 field：
     *                 - 若剩余维度 > step: 用 g_i^recent。
     *                 - 若剩余维度 <= step: 用 “尾块斜率” g_i^tail，考虑 full-dim 时的 LB 跳跃。
     *             * 在该 field 上再推进一块（或尾块），更新 accum_dist_sq / LB_i^2 / 斜率。
     *             * 若该 field 达到 full-dim，则转为精确距离，从 k_dist / max_dist 中扣除，并从 AESC 中移除。
     *             * 每次推进之后用原来的 tmp_LB_sq(DCHT) 做 early stop。
     */
    float compare_weight_AESC_newTryV6_adaptiveSampling_adaptiveProj(
            int &use,
            float &dec1_cost, float &dec2_cost, int &dec,
            const std::vector<float *> &base1, unsigned id1,
            const std::vector<float *> &base2, unsigned id2,
            const std::vector<unsigned> &dim_list,
            const std::vector<float> &dim_sqrt,
            const std::vector<std::vector<float>> &dim_thresh_rate_square, // (1+eps)^2 的表
            const std::vector<int> &needCalField,
            const std::vector<int> &need_calcu_NoProj,
            const std::vector<int> &need_calcu_WithProj,
            std::vector<bool> &do_proj,        // 保留接口，不使用
            std::vector<float> &weight,
            float k_dist, float max_dist, float diameter,
            float epsilon0,                    // 不再使用
            unsigned step = 32,
            float alpha = 0.5f                 // 作为 p_alpha 使用（预处理里已经用了）
    )
    {
        // ======= 1. 先处理 need_calcu_NoProj: full-dim 精确距离 + 早停止 =======
        float dist_no_proj = 0.0f;
        const float *a;
        const float *b;
        float d0, d1, d2, d3;

        for (int field : need_calcu_NoProj) {
            unsigned dim = dim_list[field];
            const float *a_ptr = base1[field] + id1 * dim;
            const float *b_ptr = base2[field] + id2 * dim;

            float dist_sq = 0.0f;
            const float *last = a_ptr + dim;
            const float *unroll_group = last - 3;

            a = a_ptr;
            b = b_ptr;

            while (a < unroll_group) {
                d0 = a[0] - b[0];
                d1 = a[1] - b[1];
                d2 = a[2] - b[2];
                d3 = a[3] - b[3];
                dist_sq += d0 * d0 + d1 * d1 + d2 * d2 + d3 * d3;
                a += 4;
                b += 4;
            }
            while (a < last) {
                d0 = a[0] - b[0];
                a++; b++;
                dist_sq += d0 * d0;
            }

            float dist = std::sqrt(dist_sq);
            dist_no_proj += weight[field] * dist;

            if (dist_no_proj > max_dist) {
                // 直接可以剪枝
                return -1.0f;
            }
        }

        if (need_calcu_WithProj.empty()) {
            // 没有 AESC 部分，直接返回 full-dim 结果
            return dist_no_proj;
        }

        // 把 NoProj 部分从阈值中扣除，只对剩余字段做 AESC
        k_dist -= dist_no_proj;
        max_dist -= dist_no_proj;
        float k_dist_sq = k_dist * k_dist;

        // ======= 2. 对 need_calcu_WithProj 做 AESC：准备元数据 =======
        const int num_fields = static_cast<int>(need_calcu_WithProj.size());
        int conti_fields = num_fields;  // 当前仍在 “估计 + shrink” 中的 field 数
        const int total_field_num = static_cast<int>(base1.size());

        struct FieldMeta {
            const float *a_ptr;
            const float *b_ptr;
            float weight;
            unsigned dim;               // full-dim
            unsigned used;              // 已经使用的维度数
            float accum_dist_sq;        // ∑ (a-b)^2 到 used 为止
            float accum_weighted_dist_sq; // accum_dist_sq * weight^2
            float dim_ratio_sqrt;       // sqrt(D/used)
            float numer;                // dim_ratio_sqrt^2 * accum_weighted_dist_sq
            float LB_sq;                // 单 field 的 LB_i^2（在当前 num_conti 下）
            float slope_recent;         // 最近一块的斜率（ΔLB_i^2 / Δused_i）
            bool  finished;
            int   field_id;             // 原来的 field 下标，便于 debug
        };

        FieldMeta fields[32];  // 假设 field 数不超过 32

        for (int i = 0; i < num_fields; ++i) {
            int f = need_calcu_WithProj[i];
            unsigned dim = dim_list[f];
            fields[i] = {
                base1[f] + id1 * dim,   // a_ptr
                base2[f] + id2 * dim,   // b_ptr
                weight[f],
                dim,
                0u,                     // used
                0.0f,                   // accum_dist_sq
                0.0f,                   // accum_weighted_dist_sq
                0.0f,                   // dim_ratio_sqrt
                0.0f,                   // numer
                0.0f,                   // LB_sq
                0.0f,                   // slope_recent
                false,                  // finished
                f                       // field_id
            };
        }

        // 一个小工具：根据当前 conti_fields 得到 dim_thresh_rate_square 的行索引
        auto get_thresh_row_index = [&](int conti) -> int {
            // 和 V4 保持一致： (1 << total_field_num) + conti_fields - 1
            return (1 << total_field_num) + conti - 1;
        };

        // 当前阈值行
        int thresh_row_idx = get_thresh_row_index(conti_fields);
        const std::vector<float> *thresh_row = &dim_thresh_rate_square[thresh_row_idx];

        float tmp_LB_sq = 0.0f;  // ∑ LB_i^2，用来和 k_dist^2 / max_dist^2 做比较

        // 一个重建所有 LB_i^2 的小函数（在 conti_fields 变化后调用）
        auto rebuild_LB_sq_all = [&]() {
            tmp_LB_sq = 0.0f;
            thresh_row_idx = get_thresh_row_index(conti_fields);
            thresh_row = &dim_thresh_rate_square[thresh_row_idx];

            for (int i = 0; i < num_fields; ++i) {
                FieldMeta &field = fields[i];
                if (field.finished || field.used == 0) {
                    field.LB_sq = 0.0f;
                    continue;
                }
                // dim_ratio_sqrt = sqrt(D/used) = dim_sqrt[D-1] / dim_sqrt[used-1]
                field.dim_ratio_sqrt =
                    dim_sqrt[field.dim - 1] / dim_sqrt[field.used - 1];

                field.numer =
                    field.dim_ratio_sqrt * field.dim_ratio_sqrt *
                    field.accum_weighted_dist_sq;

                float denom = (*thresh_row)[field.used - 1];    // (1+eps)^2
                field.LB_sq = field.numer / denom;
                tmp_LB_sq += field.LB_sq;
            }
        };

        // 一个 early stop 检查函数，完全复用 V4 的 DCHT 风格逻辑
        auto try_early_stop = [&]() -> float {
            if (tmp_LB_sq > k_dist_sq * (1.0f + 1e-4f)) {
                float max_dist_sq = max_dist * max_dist;
                if (tmp_LB_sq > max_dist_sq * (1.0f + 1e-4f)) {
                    // 一定 > k_dist 且 > max_dist，可以直接剪枝
                    return -1.0f;
                } else {
                    // 估计剩余距离：∑ w_i * sqrt( (D/used) * partial_sq )
                    float est_remain = 0.0f;
                    for (int i = 0; i < num_fields; ++i) {
                        FieldMeta &field = fields[i];
                        if (field.finished || field.used == 0) continue;
                        // sqrt(accum_weighted_dist_sq) * dim_ratio_sqrt
                        float est_i =
                            std::sqrt(field.accum_weighted_dist_sq) *
                            field.dim_ratio_sqrt;
                        est_remain += est_i;
                    }
                    if (est_remain <= max_dist) {
                        return dist_no_proj + est_remain;
                    }
                }
            }
            return std::numeric_limits<float>::quiet_NaN();
        };

        // ======= 3. 初始化：每个 field 先推进一块 step 维 =======
        bool need_rebuild = false;

        for (int i = 0; i < num_fields; ++i) {
            FieldMeta &field = fields[i];
            if (field.finished) continue;

            unsigned remain = field.dim - field.used;
            unsigned delta = std::min(step, remain);
            if (delta == 0) continue;

            // 计算这一块的 ∑(a-b)^2
            a = field.a_ptr + field.used;
            b = field.b_ptr + field.used;
            const float *last = a + delta;
            const float *unroll_group = last - 3;

            float dist_sq_block = 0.0f;

            while (a < unroll_group) {
                d0 = a[0] - b[0];
                d1 = a[1] - b[1];
                d2 = a[2] - b[2];
                d3 = a[3] - b[3];
                dist_sq_block += d0 * d0 + d1 * d1 + d2 * d2 + d3 * d3;
                a += 4;
                b += 4;
            }
            while (a < last) {
                d0 = a[0] - b[0];
                a++; b++;
                dist_sq_block += d0 * d0;
            }

            field.used += delta;
            field.accum_dist_sq += dist_sq_block;
            field.accum_weighted_dist_sq =
                field.accum_dist_sq * field.weight * field.weight;

            if (field.used == field.dim) {
                // 这一块直接把整个 field 算完：转为精确距离
                float dist_full = std::sqrt(field.accum_dist_sq) * field.weight;
                dist_no_proj += dist_full;
                k_dist       -= dist_full;
                max_dist     -= dist_full;
                k_dist_sq     = k_dist * k_dist;

                field.finished = true;
                field.LB_sq = 0.0f;
                field.slope_recent = 0.0f;

                --conti_fields;
                need_rebuild = true;
            } else {
                // 还有剩余维度，正常初始化 LB_i^2 和斜率
                field.dim_ratio_sqrt =
                    dim_sqrt[field.dim - 1] / dim_sqrt[field.used - 1];
                field.numer =
                    field.dim_ratio_sqrt * field.dim_ratio_sqrt *
                    field.accum_weighted_dist_sq;

                float denom = (*thresh_row)[field.used - 1];
                field.LB_sq = field.numer / denom;
                tmp_LB_sq += field.LB_sq;

                // 从 0 到 used 的平均斜率
                field.slope_recent = (field.used > 0)
                                    ? (field.LB_sq / static_cast<float>(field.used))
                                    : 0.0f;
            }
        }

        if (conti_fields <= 0) {
            // 所有 withProj field 都已经 full-dim
            return dist_no_proj;
        }
        if (need_rebuild) {
            rebuild_LB_sq_all();
            need_rebuild = false;
        }

        // 初始化完成后做一次 early stop 检查
        {
            float early = try_early_stop();
            if (!std::isnan(early)) {
                return early;
            }
        }

        // ======= 4. 主循环：block 粒度贪心 + 尾块斜率 =======
        while (conti_fields > 0) {
            // ---- 4.1 选一个 field：比较斜率 g_i ----
            int best_idx = -1;
            float best_slope = -1.0f;

            for (int i = 0; i < num_fields; ++i) {
                FieldMeta &field = fields[i];
                if (field.finished || field.used == field.dim) continue;

                unsigned remain = field.dim - field.used;
                float slope = 0.0f;

                if (remain <= step) {
                    // 尾块：用 full-dim 跳跃近似的斜率
                    // full-approx 的 LB_i^2 ≈ numer (不再除 (1+eps)^2)
                    float LB_sq_current = field.LB_sq;
                    float LB_sq_full_approx = field.numer;  // numer = w^2 * (D/used)*partial_sq
                    float delta_LB_sq_jump =
                        std::max(0.0f, LB_sq_full_approx - LB_sq_current);
                    slope = delta_LB_sq_jump / static_cast<float>(remain);
                } else {
                    // 非尾部：用最近一块的经验斜率
                    slope = field.slope_recent;
                }

                if (slope > best_slope) {
                    best_slope = slope;
                    best_idx = i;
                }
            }

            if (best_idx < 0) {
                // 理论上不会发生，做一个保险：直接把剩余全部算完
                for (int i = 0; i < num_fields; ++i) {
                    FieldMeta &field = fields[i];
                    if (field.finished || field.used == field.dim) continue;

                    unsigned remain = field.dim - field.used;
                    if (remain == 0) continue;

                    a = field.a_ptr + field.used;
                    b = field.b_ptr + field.used;
                    const float *last = a + remain;
                    const float *unroll_group = last - 3;

                    float dist_sq_block = 0.0f;
                    while (a < unroll_group) {
                        d0 = a[0] - b[0];
                        d1 = a[1] - b[1];
                        d2 = a[2] - b[2];
                        d3 = a[3] - b[3];
                        dist_sq_block += d0 * d0 + d1 * d1 + d2 * d2 + d3 * d3;
                        a += 4;
                        b += 4;
                    }
                    while (a < last) {
                        d0 = a[0] - b[0];
                        a++; b++;
                        dist_sq_block += d0 * d0;
                    }

                    field.used += remain;
                    field.accum_dist_sq += dist_sq_block;
                    float dist_full = std::sqrt(field.accum_dist_sq) * field.weight;
                    dist_no_proj += dist_full;
                }
                return dist_no_proj;
            }

            FieldMeta &best = fields[best_idx];
            unsigned remain_best = best.dim - best.used;
            unsigned delta = std::min(step, remain_best);
            bool will_finish = (delta == remain_best);

            // ---- 4.2 在 best field 上推进 delta 维 ----
            a = best.a_ptr + best.used;
            b = best.b_ptr + best.used;
            const float *last = a + delta;
            const float *unroll_group = last - 3;

            float dist_sq_block = 0.0f;
            while (a < unroll_group) {
                d0 = a[0] - b[0];
                d1 = a[1] - b[1];
                d2 = a[2] - b[2];
                d3 = a[3] - b[3];
                dist_sq_block += d0 * d0 + d1 * d1 + d2 * d2 + d3 * d3;
                a += 4;
                b += 4;
            }
            while (a < last) {
                d0 = a[0] - b[0];
                a++; b++;
                dist_sq_block += d0 * d0;
            }

            float LB_sq_old = best.LB_sq;

            best.used += delta;
            best.accum_dist_sq += dist_sq_block;
            best.accum_weighted_dist_sq =
                best.accum_dist_sq * best.weight * best.weight;

            if (will_finish) {
                // 直接 full-dim 精确距离，然后从 AESC 移除
                float dist_full = std::sqrt(best.accum_dist_sq) * best.weight;
                dist_no_proj += dist_full;
                k_dist   -= dist_full;
                max_dist -= dist_full;
                k_dist_sq = k_dist * k_dist;

                // 从 LB^2 聚合中移除旧 contribution
                tmp_LB_sq -= LB_sq_old;
                if (tmp_LB_sq < 0.0f) tmp_LB_sq = 0.0f;

                best.finished = true;
                best.LB_sq = 0.0f;
                best.slope_recent = 0.0f;

                --conti_fields;
                if (conti_fields <= 0) {
                    // 所有 field 都 full-dim
                    return dist_no_proj;
                }
                // conti_fields 变化，需要重建 LB_i^2
                need_rebuild = true;
            } else {
                // 非尾部：更新 LB_i^2 和最近斜率
                // 先更新 dim_ratio_sqrt / numer
                best.dim_ratio_sqrt =
                    dim_sqrt[best.dim - 1] / dim_sqrt[best.used - 1];
                best.numer =
                    best.dim_ratio_sqrt * best.dim_ratio_sqrt *
                    best.accum_weighted_dist_sq;

                // 此时 conti_fields 未变化，thresh_row 仍然有效
                float denom = (*thresh_row)[best.used - 1];
                float LB_sq_new = best.numer / denom;

                tmp_LB_sq += (LB_sq_new - LB_sq_old);
                best.slope_recent =
                    (LB_sq_new - LB_sq_old) / static_cast<float>(delta);
                best.LB_sq = LB_sq_new;
            }

            if (need_rebuild) {
                rebuild_LB_sq_all();
                need_rebuild = false;
            }

            // ---- 4.3 每一小步推进之后做一次 early stop 检查 ----
            float early = try_early_stop();
            if (!std::isnan(early)) {
                return early;
            }
        }

        // 正常结束：所有 field 都 full-dim 或无法提前终止
        return dist_no_proj;
    }

    // /** XMT, 2025.12.08: (type 3, V6) 效果不如type2，但V6-type2的效果还是不如Type4
