                        float tmp_dist_sq = 0.0;
                        a = fields[0].a_ptr;
                        b = fields[0].b_ptr;
                        for (unsigned j = 0; j < fields[0].dim; j++)
                        {
                            // float d = a[j] - b[j];
                            d0 = a[0] - b[0];
                            a++, b++;
                            tmp_dist_sq += d0 * d0;
                            std::cout << d0 << ", ";
                            if ((j + 1) % step == 0)
                            {
                                std::cout << "\n          -- with d = " << (j + 1) << ", tmp_dist_sq = " << tmp_dist_sq << std::endl;
                            }
                        }
                        std::cout << "\n          -- with d = " << fields[0].dim << ", tmp_dist_sq = " << tmp_dist_sq << std::endl;
                        true_dist = compare_smart_weight_print(base1, id1, base2, id2, dim_list, need_calcu, weight);
                        std::cout << "----------------------------------" << std::endl;

                        // ### v1: 4-loop
                        a = fields[0].a_ptr;
                        b = fields[0].b_ptr;
                        d0 = a[0] - b[0];
                        d1 = a[1] - b[1];
                        d2 = a[2] - b[2];
                        d3 = a[3] - b[3];
                        tmp_dist_sq = 0.0;
                        tmp_dist_sq += d0 * d0 + d1 * d1 + d2 * d2 + d3 * d3;
                        std::cout << "d0: " << d0 << "d1: " << d1 << "d2: " << d2 << "d3: " << d3 << std::endl;
                        std::cout << std::fixed << std::setprecision(30) << " -- 4loop-dist: " << tmp_dist_sq << std::endl;
                        // ### v2: 1-loop
